const key = (id) => `action:${id}`;
/** Back the legacy ActionStore shape with state.kv. Durable iff `state` is durable. */
export function kvActionStore(state, opts) {
    return {
        put: (id, snap, ttlMs) => state.kv.set(key(id), snap, ttlMs ?? opts?.defaultTtlMs),
        get: (id) => state.kv.get(key(id)),
        consume: (id) => state.kv.consume(key(id)),
        delete: (id) => state.kv.delete(key(id)),
    };
}
